CREATE FUNCTION "public"."accept_message_request"(p_conversation_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  v_user_id uuid := auth.uid();
  v_conv record;
begin
  if v_user_id is null then
    raise exception 'unauthorized';
  end if;

  select * into v_conv from public.conversations where id = p_conversation_id;
  if v_conv is null then
    raise exception 'conversation not found';
  end if;
  if v_conv.is_group then
    raise exception 'not a request';
  end if;
  if v_conv.request_status <> 'pending' then
    raise exception 'not a pending request';
  end if;

  -- Only the non-sender (the receiver) can accept.
  if v_conv.request_sender_id = v_user_id then
    raise exception 'sender cannot accept own request';
  end if;
  if v_conv.user_1 <> v_user_id and v_conv.user_2 <> v_user_id then
    raise exception 'not a party to this conversation';
  end if;

  update public.conversations
    set request_status = 'accepted',
        is_request = false
    where id = p_conversation_id;
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."accept_message_request"(p_conversation_id uuid) TO "service_role";

CREATE FUNCTION "public"."add_business_member"(p_business_id uuid, p_username text, p_role text DEFAULT 'contributor'::text) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO ''
AS $qa_source$
declare v_target uuid; v_name text;
begin
  if auth.uid() is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  -- Serialize these legacy writers before reading membership or owner counts.
  perform 1 from public.profiles where id = p_business_id for update;
  if not found then raise exception 'Business profile not found'; end if;
  if public.is_business_owner(p_business_id) is not true then
    raise exception 'Only an owner can add team members' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('owner', 'manager', 'contributor') then
    raise exception 'Role must be owner, manager or contributor';
  end if;

  select id, full_name into v_target, v_name
  from public.profiles where lower(username) = lower(trim(p_username));
  if v_target is null then raise exception 'No account with that username'; end if;
  if v_target = p_business_id then raise exception 'A business cannot be its own member'; end if;

  if p_role <> 'owner' and exists (
    select 1 from public.business_members where business_id = p_business_id
      and member_id = v_target and role = 'owner'
  ) and (select count(*) from public.business_members where business_id = p_business_id and role = 'owner') <= 1 then
    raise exception 'A business must keep at least one owner';
  end if;

  insert into public.business_members (business_id, member_id, role)
  values (p_business_id, v_target, p_role)
  on conflict (business_id, member_id) do update set role = excluded.role;

  return jsonb_build_object('member_id', v_target, 'full_name', v_name, 'role', p_role);
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."add_business_member"(p_business_id uuid, p_username text, p_role text) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."add_business_member"(p_business_id uuid, p_username text, p_role text) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."add_business_member"(p_business_id uuid, p_username text, p_role text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."add_business_member"(p_business_id uuid, p_username text, p_role text) TO "service_role";

CREATE FUNCTION "public"."add_memory_page"(p_story_id uuid, p_caption text DEFAULT NULL::text, p_style text DEFAULT 'polaroid'::text, p_album_id uuid DEFAULT NULL::uuid) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid; v_album uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_album_id is not null then
    select id into v_album from memory_albums where id = p_album_id and user_id = auth.uid();
    if v_album is null then raise exception 'not your book'; end if;
  else
    select id into v_album from memory_albums where user_id = auth.uid() and is_default;
    if v_album is null then
      insert into memory_albums (user_id, is_default) values (auth.uid(), true) returning id into v_album;
    end if;
  end if;
  insert into memory_pages (user_id, album_id, story_id, media_url, media_type, thumbnail_url, caption, style, taken_at, sort_order)
  select auth.uid(), v_album, s.id, s.media_url, s.media_type, s.thumbnail_url,
         coalesce(p_caption, s.caption), coalesce(p_style, 'polaroid'), s.created_at,
         coalesce((select max(sort_order) + 1 from memory_pages where album_id = v_album), 0)
  from stories s
  where s.id = p_story_id and s.user_id = auth.uid()
  on conflict (album_id, story_id) do nothing
  returning id into v_id;
  return v_id;
end;
$qa_source$;

