CREATE FUNCTION "public"."bump_post_views"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  -- The author looking at their own post is not a view.
  if exists (select 1 from public.posts p where p.id = new.post_id and p.user_id = new.user_id) then
    return new;
  end if;
  -- One view per person per post: if this viewer already has a seen row, do not count again.
  if (select count(*) from public.post_seen s where s.post_id = new.post_id and s.user_id = new.user_id) > 1 then
    return new;
  end if;
  update public.posts set views_count = coalesce(views_count, 0) + 1 where id = new.post_id;
  return new;
end
$qa_source$;

