CREATE FUNCTION "public"."can_comment"(p_post_id uuid) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
  select case
    when p.user_id = auth.uid() then true
    when p.comment_policy = 'off' then false
    when p.comment_policy = 'following' then exists (select 1 from follows f where f.follower_id = p.user_id and f.following_id = auth.uid())
    when p.comment_policy = 'followers' then exists (select 1 from follows f where f.follower_id = auth.uid() and f.following_id = p.user_id)
    when p.comment_policy = 'mentioned' then exists (select 1 from post_mentions m where m.post_id = p.id and m.mentioned_user_id = auth.uid())
    else true end
  from posts p where p.id = p_post_id;
$qa_source$;

