GRANT EXECUTE ON FUNCTION "public"."can_view_post"(p_post_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."can_view_post"(p_post_id uuid) TO "service_role";

CREATE FUNCTION "public"."can_view_profile"(p_profile_id uuid) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
  select coalesce((
    select case
      when p.id = auth.uid() then true
      when exists (
        select 1 from blocked_users b
        where (b.blocker_id = auth.uid() and b.blocked_id = p.id)
           or (b.blocker_id = p.id and b.blocked_id = auth.uid())
      ) then false
      when p.profile_visibility = 'private' then exists (
        select 1 from follows f
        where f.follower_id = auth.uid() and f.following_id = p.id
      )
      else true
    end
