CREATE FUNCTION "public"."check_email_allowed"(p_email text) RETURNS json
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_domain TEXT;
  v_blocked BOOLEAN;
  v_is_school BOOLEAN;
BEGIN
  v_domain := lower(split_part(p_email, '@', 2));
  v_blocked := public.is_email_blocked(p_email);
  v_is_school := public.is_verified_school_domain(p_email);

  RETURN json_build_object(
    'allowed', NOT v_blocked,
    'domain', v_domain,
    'is_school_domain', v_is_school,
    'reason', CASE WHEN v_blocked THEN 'disposable_email_not_allowed' ELSE null END
  );
END;
$qa_source$;

