CREATE FUNCTION "public"."create_community"(p_name text, p_description text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_join_mode text DEFAULT 'open'::text, p_cover_color text DEFAULT 'sky'::text, p_rules text DEFAULT NULL::text) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid;
begin
  if p_name is null or length(trim(p_name)) < 3 or length(trim(p_name)) > 60 then
    raise exception 'Community names run 3 to 60 characters';
  end if;
  if p_join_mode not in ('open','approval','invite') then raise exception 'Bad join mode'; end if;
  if exists (select 1 from communities where owner_id = auth.uid() and status = 'active' and parent_id is null and lower(name) = lower(trim(p_name))) then
    raise exception 'You already have a community called %', trim(p_name);
  end if;
  insert into communities (owner_id, name, description, category, join_mode, cover_color, rules, member_count, status, last_activity_at)
  values (auth.uid(), trim(p_name), nullif(trim(coalesce(p_description,'')),''), p_category, p_join_mode, coalesce(p_cover_color,'sky'), nullif(trim(coalesce(p_rules,'')),''), 0, 'active', now())
  returning id into v_id;
  insert into community_members (community_id, user_id, role, status, status_at) values (v_id, auth.uid(), 'owner', 'active', now());
  return v_id;
end $qa_source$;

