CREATE FUNCTION "public"."create_community_invite_link"(p_community uuid, p_expires_days integer DEFAULT 7, p_max_uses integer DEFAULT NULL::integer) RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_token text;
begin
  if not community_is_mod(p_community) then raise exception 'Only the owner and moderators make invite links'; end if;
  update community_invite_links set revoked_at = now() where community_id = p_community and revoked_at is null;
  v_token := substr(md5(random()::text || clock_timestamp()::text || p_community::text), 1, 12) || substr(md5(random()::text || auth.uid()::text), 1, 8);
  insert into community_invite_links (community_id, token, created_by, expires_at, max_uses)
  values (p_community, v_token, auth.uid(), case when p_expires_days is null or p_expires_days <= 0 then null else now() + make_interval(days => least(p_expires_days, 365)) end, p_max_uses);
  return v_token;
end $qa_source$;

