CREATE FUNCTION "public"."create_sub_community"(p_parent uuid, p_name text, p_description text DEFAULT NULL::text, p_join_mode text DEFAULT 'open'::text, p_cover_color text DEFAULT 'sky'::text) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid; v_cat text;
begin
  if not community_is_mod(p_parent) then raise exception 'Only the owner and moderators create sub-groups'; end if;
  if exists (select 1 from communities where id = p_parent and parent_id is not null) then raise exception 'Sub-groups cannot have their own sub-groups'; end if;
  if p_name is null or length(trim(p_name)) < 3 or length(trim(p_name)) > 60 then raise exception 'Names run 3 to 60 characters'; end if;
  if p_join_mode not in ('open','approval','invite') then raise exception 'Bad join mode'; end if;
  select category into v_cat from communities where id = p_parent;
  insert into communities (owner_id, name, description, category, join_mode, cover_color, rules, member_count, status, last_activity_at, parent_id)
  values (auth.uid(), trim(p_name), nullif(trim(coalesce(p_description,'')),''), v_cat, p_join_mode, coalesce(p_cover_color,'sky'), null, 0, 'active', now(), p_parent)
  returning id into v_id;
  insert into community_members (community_id, user_id, role, status, status_at) values (v_id, auth.uid(), 'owner', 'active', now());
  return v_id;
end $qa_source$;

