CREATE FUNCTION "public"."delete_community"(p_community uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if not exists (select 1 from communities where id = p_community and owner_id = auth.uid()) then
    raise exception 'Only the owner can delete a community';
  end if;
  update communities set status = 'archived', last_activity_at = now() where id = p_community or parent_id = p_community;
  delete from community_members where community_id = p_community or community_id in (select id from communities where parent_id = p_community);
  delete from community_join_requests where community_id = p_community;
  update community_invites set status = 'revoked', responded_at = now() where community_id = p_community and status = 'invited';
  update community_invite_links set revoked_at = now() where community_id = p_community and revoked_at is null;
end $qa_source$;

