CREATE FUNCTION "public"."end_meeting"(p_meeting_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'Not authenticated'; end if;

  update public.meetings
     set ended_at = now()
   where id = p_meeting_id and host_id = v_user and ended_at is null;

  if not found then raise exception 'Meeting not found or not yours'; end if;

  -- Mark all remaining participants as left
  update public.meeting_participants
     set left_at = now()
   where meeting_id = p_meeting_id and left_at is null;
end;
