CREATE FUNCTION "public"."enforce_comment_policy"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_author uuid; v_words text[];
begin
  if not public.can_comment(new.post_id) then raise exception 'Comments are limited on this post'; end if;
  select p.user_id into v_author from posts p where p.id = new.post_id;
  select coalesce(hidden_words, '{}') into v_words from profiles where id = v_author;
  if v_words is not null and array_length(v_words, 1) > 0 then
    if exists (select 1 from unnest(v_words) w where lower(coalesce(new.body, new.content, '')) like '%' || lower(w) || '%') then
      new.hidden_at := now();
    end if;
  end if;
  return new;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."enforce_comment_policy"() FROM PUBLIC, anon, authenticated, service_role, postgres;

