GRANT EXECUTE ON FUNCTION "public"."enforce_comment_policy"() TO "anon";

GRANT EXECUTE ON FUNCTION "public"."enforce_comment_policy"() TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."enforce_comment_policy"() TO "service_role";

CREATE FUNCTION "public"."ensure_community_conversation"(p_community uuid) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  v_conv uuid;
  v_me uuid := auth.uid();
  v_name text;
  v_emoji text;
begin
  if v_me is null then raise exception 'not signed in'; end if;
  if not exists (select 1 from public.community_members where community_id = p_community and user_id = v_me) then
    raise exception 'not a member of this community';
  end if;
  select conversation_id, name, emoji into v_conv, v_name, v_emoji from public.communities where id = p_community;
  if v_conv is null then
    insert into public.conversations (user_1, user_2, type, is_group, context, group_name, group_emoji, last_message, last_message_time)
    values (v_me, v_me, 'group', true, 'personal', v_name, v_emoji, '', now())
    returning id into v_conv;
    update public.communities set conversation_id = v_conv where id = p_community;
  end if;
  insert into public.conversation_members (conversation_id, user_id)
  select v_conv, m.user_id from public.community_members m
  where m.community_id = p_community
    and not exists (select 1 from public.conversation_members cm where cm.conversation_id = v_conv and cm.user_id = m.user_id);
  return v_conv;
end
$qa_source$;

REVOKE ALL ON FUNCTION "public"."ensure_community_conversation"(p_community uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."ensure_community_conversation"(p_community uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."ensure_community_conversation"(p_community uuid) TO "postgres";

