CREATE FUNCTION "public"."fn_notify_message_reaction"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_msg_sender_id uuid;
  v_conversation_id uuid;
  v_actor_name text;
BEGIN
  -- Get message sender and conversation
  SELECT sender_id, conversation_id
  INTO v_msg_sender_id, v_conversation_id
  FROM messages
  WHERE id = NEW.message_id;

  -- Skip if message not found or self-reaction
  IF v_msg_sender_id IS NULL OR v_msg_sender_id = NEW.user_id THEN
    RETURN NEW;
  END IF;

  -- Get actor name
  SELECT coalesce(full_name, username, 'Someone') INTO v_actor_name
  FROM profiles
  WHERE id = NEW.user_id;

  -- Insert notification
  INSERT INTO notifications (
    recipient_id,
    actor_id,
    type,
    message,
    body_preview,
    data
  ) VALUES (
    v_msg_sender_id,
    NEW.user_id,
    'message_reaction',
    v_actor_name || ' reacted ' || NEW.emoji || ' to your message',
    NEW.emoji,
    jsonb_build_object(
      'conversation_id', v_conversation_id,
      'message_id', NEW.message_id,
      'emoji', NEW.emoji
    )
  );

  RETURN NEW;
END;
$qa_source$;

