CREATE FUNCTION "public"."gen_meeting_room_name"() RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
declare
  v_name text;
  v_exists boolean;
begin
  loop
    -- 8 char alphanumeric room name like "k3xp9q2m"
    v_name := lower(substring(md5(random()::text || clock_timestamp()::text), 1, 8));
    select exists(select 1 from public.meetings where room_name = v_name) into v_exists;
    exit when not v_exists;
  end loop;
  return v_name;
end;
$qa_source$;

