CREATE FUNCTION "public"."get_business_conversations"(p_business_id uuid) RETURNS TABLE(conversation_id uuid, context text, other_id uuid, other_name text, other_username text, other_avatar text, last_text text, last_at timestamp with time zone, last_sender uuid, unread integer, is_request boolean)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select c.id,
         c.context,
         pr.id, pr.full_name, pr.username, pr.avatar_url,
         lm.text,
         lm.created_at,
         lm.sender_id,
         (select count(*)::int from messages m
           where m.conversation_id = c.id
             and m.receiver_id = p_business_id
             and m.sender_id <> p_business_id
             and m.read_at is null) as unread,
         not exists (select 1 from messages mb
           where mb.conversation_id = c.id
             and mb.sender_id = p_business_id) as is_request
  from conversations c
  join profiles pr
    on pr.id = case when c.user_1 = p_business_id then c.user_2 else c.user_1 end
  left join lateral (
    select m.text, m.created_at, m.sender_id
    from messages m
    where m.conversation_id = c.id
    order by m.created_at desc
    limit 1
  ) lm on true
  where is_business_member(p_business_id)
    and c.type = 'direct'
    and (c.user_1 = p_business_id or c.user_2 = p_business_id)
  order by lm.created_at desc nulls last;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_business_conversations"(p_business_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_business_conversations"(p_business_id uuid) TO PUBLIC;

