CREATE FUNCTION "public"."get_business_reviews"(p_business_id uuid, p_limit integer DEFAULT 30) RETURNS TABLE(review_id uuid, rating smallint, body text, created_at timestamp with time zone, reviewer_id uuid, reviewer_name text, reviewer_username text, reviewer_avatar text, is_mine boolean)
LANGUAGE sql
STABLE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select r.id, r.rating, r.body, r.created_at,
         pr.id, pr.full_name, pr.username, pr.avatar_url,
         (r.user_id = auth.uid())
  from business_reviews r
  join business_profiles b on b.id = r.business_id
  join profiles pr on pr.id = r.user_id
  where b.profile_id = p_business_id
  order by (r.user_id = auth.uid()) desc, r.created_at desc
  limit least(coalesce(p_limit, 30), 100);
$qa_source$;

