CREATE FUNCTION "public"."get_communities"(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, name text, description text, icon_url text, cover_color text, category text, join_mode text, member_count integer, last_activity_at timestamp with time zone, is_member boolean, my_role text, has_pending boolean, owner_username text)
LANGUAGE sql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select c.id, c.name, c.description, c.icon_url, c.cover_color, c.category,
         c.join_mode, c.member_count, c.last_activity_at,
         (m.user_id is not null) as is_member,
         m.role as my_role,
         exists (select 1 from community_join_requests r where r.community_id = c.id and r.user_id = auth.uid()) as has_pending,
         p.username as owner_username
  from communities c
  left join profiles p on p.id = c.owner_id
  left join community_members m on m.community_id = c.id and m.user_id = auth.uid()
  where c.status = 'active' and c.name is not null and c.owner_id is not null and c.parent_id is null
    and (p_query is null or trim(p_query) = '' or c.name ilike '%' || trim(p_query) || '%' or c.description ilike '%' || trim(p_query) || '%')
  order by (m.user_id is not null) desc, c.last_activity_at desc, c.member_count desc
  limit least(coalesce(p_limit, 30), 60);
$qa_source$;

