CREATE FUNCTION "public"."get_community"(p_community uuid) RETURNS TABLE(id uuid, name text, description text, icon_url text, cover_color text, category text, rules text, join_mode text, member_count integer, is_member boolean, my_role text, has_pending boolean, owner_username text, has_invite boolean, my_status text, is_banned boolean, parent_id uuid, parent_name text, sub_count integer, announcement_count integer)
LANGUAGE sql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select c.id, c.name, c.description, c.icon_url, c.cover_color, c.category,
         c.rules, c.join_mode, c.member_count,
         (m.user_id is not null), m.role,
         exists (select 1 from community_join_requests r where r.community_id = c.id and r.user_id = auth.uid()),
         p.username,
         exists (select 1 from community_invites i where i.community_id = c.id and i.user_id = auth.uid() and i.status = 'invited'),
         m.status,
         exists (select 1 from community_bans b where b.community_id = c.id and b.user_id = auth.uid()),
         c.parent_id,
         (select pc.name from communities pc where pc.id = c.parent_id),
         (select count(*)::int from communities sc where sc.parent_id = c.id and sc.status = 'active'),
         (select count(*)::int from community_announcements a where a.community_id = c.id)
  from communities c
  left join profiles p on p.id = c.owner_id
  left join community_members m on m.community_id = c.id and m.user_id = auth.uid()
  where c.id = p_community and c.status = 'active';
$qa_source$;

