CREATE FUNCTION "public"."get_community_conversation"(p_community uuid) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_name text; v_emoji text;
begin
  if not exists (select 1 from community_members where community_id = p_community and user_id = auth.uid()) then
    raise exception 'Join the community to open its chat';
  end if;
  select name, coalesce(emoji, '🌐') into v_name, v_emoji from communities where id = p_community and status = 'active';
  if v_name is null then raise exception 'No such community'; end if;
  return get_or_create_group_conversation('community', p_community, v_name, v_emoji, auth.uid());
end $qa_source$;

