CREATE FUNCTION "public"."get_community_invites"(p_community uuid, p_limit integer DEFAULT 60) RETURNS TABLE(user_id uuid, full_name text, username text, avatar_url text, invited_by uuid, created_at timestamp with time zone)
LANGUAGE sql
