CREATE FUNCTION "public"."get_community_members"(p_community uuid, p_limit integer DEFAULT 60) RETURNS TABLE(user_id uuid, full_name text, username text, avatar_url text, role text, status text)
LANGUAGE sql
VOLATILE
SECURITY DEFINER
