CREATE FUNCTION "public"."get_market_feed"(p_category text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0) RETURNS SETOF marketplace_listings
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
