CREATE FUNCTION "public"."get_or_create_group_conversation"(p_group_type text, p_group_id uuid, p_group_name text, p_group_emoji text, p_user_id uuid) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
declare
  v_conv_id uuid;
begin
  select id into v_conv_id
  from conversations
  where type = 'group'
    and group_type = p_group_type
    and group_ref_id = p_group_id
  limit 1;

  if v_conv_id is null then
    insert into conversations (
      user_1, user_2, type, is_group,
      group_name, group_emoji, group_type, group_ref_id,
      last_message, last_message_time
    ) values (
      p_user_id, null, 'group', true,
      p_group_name, p_group_emoji, p_group_type, p_group_id,
      'Group created', now()
    )
    returning id into v_conv_id;
  end if;

  -- Direct insert bypasses RLS (security definer)
  insert into conversation_members (conversation_id, user_id, role)
  values (v_conv_id, p_user_id, 'member')
  on conflict do nothing;

  return v_conv_id;
end;
$qa_source$;

