CREATE FUNCTION "public"."get_post_viewers"(p_post uuid) RETURNS TABLE(user_id uuid, full_name text, username text, avatar_url text, seen_at timestamp with time zone)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select p.id, p.full_name, p.username, p.avatar_url,
    max((to_jsonb(s)->>'created_at')::timestamptz) as seen_at
  from public.post_seen s
  join public.profiles p on p.id = s.user_id
  where s.post_id = p_post
    and s.user_id <> (select user_id from public.posts where id = p_post)
    and exists (select 1 from public.posts x where x.id = p_post and x.user_id = auth.uid())
  group by p.id, p.full_name, p.username, p.avatar_url
  order by seen_at desc nulls last, p.full_name;
$qa_source$;

