CREATE FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, user_id uuid, content text, likes_count integer, comments_count integer, reposts_count integer, created_at timestamp with time zone, author_name text, author_avatar text, author_username text)
LANGUAGE sql
STABLE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
AS $qa_source$
  WITH clean_tag AS (
    SELECT lower(regexp_replace(p_tag, '[^#A-Za-z0-9_]', '', 'g')) AS val
  ),
  matching AS (
    SELECT
      p.id,
      p.user_id,
      p.content,
      p.likes_count,
      p.comments_count,
      p.reposts_count,
      p.created_at
    FROM posts p, clean_tag ct
    WHERE p.content ~* (regexp_replace(ct.val, '([.*+?^${}()|[\]\\])', '\\\1', 'g') || '(?![A-Za-z0-9_])')
      AND p.content IS NOT NULL
      AND p.community_id IS NULL
    ORDER BY p.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  )
  SELECT
    m.id,
    m.user_id,
    m.content,
    m.likes_count,
    m.comments_count,
    m.reposts_count,
    m.created_at,
    coalesce(pr.full_name, 'User') AS author_name,
    pr.avatar_url AS author_avatar,
    pr.username AS author_username
  FROM matching m
  LEFT JOIN profiles pr ON pr.id = m.user_id;
$qa_source$;

