GRANT EXECUTE ON FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer, p_offset integer) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer, p_offset integer) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer, p_offset integer) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer, p_offset integer) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_posts_by_hashtag"(p_tag text, p_limit integer, p_offset integer) TO "service_role";

CREATE FUNCTION "public"."get_profile"(p_profile_id uuid) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  v_me uuid := auth.uid();
  v_row profiles;
  v_follows boolean;
  v_requested boolean;
  v_reach int;
  v_result jsonb;
begin
  select * into v_row from profiles where id = p_profile_id;
  if v_row.id is null then raise exception 'Profile not found'; end if;

  v_follows := exists (select 1 from follows
                       where follower_id = v_me and following_id = p_profile_id);
  v_requested := exists (select 1 from follow_requests
                         where requester_id = v_me and target_id = p_profile_id
                           and status = 'pending');

  if v_me = p_profile_id then
    select count(distinct s.user_id) into v_reach
    from post_seen s join posts p on p.id = s.post_id
    where p.user_id = p_profile_id;
  else
    v_reach := null;
  end if;

  select jsonb_build_object(
    'id', v_row.id,
    'full_name', v_row.full_name,
    'username', v_row.username,
    'avatar_url', v_row.avatar_url,
    'banner_url', v_row.banner_url,
    'bio', v_row.bio,
    'headline', v_row.headline,
    'workplace', v_row.workplace,
    'location', v_row.location,
    'email', v_row.email,
    'role', v_row.role,
    'degree_program', v_row.degree_program,
    'profile_visibility', coalesce(v_row.profile_visibility, 'public'),
    'account_type', coalesce(v_row.account_type, 'personal'),
    'is_verified', coalesce(v_row.is_verified, false),
    'verified_tier', v_row.verified_tier,
    'verified_category', v_row.verified_category,
    'joined_at', v_row.created_at,
    'created_at', v_row.created_at,
    'is_self', (v_me = p_profile_id),
    'viewer_follows', v_follows,
    'viewer_requested', v_requested,
    'can_view_content', (v_me = p_profile_id)
                          or coalesce(v_row.profile_visibility, 'public') <> 'private'
                          or v_follows,
    'counts', jsonb_build_object(
      'posts',     (select count(*) from posts   where user_id = p_profile_id),
      'followers', (select count(*) from follows where following_id = p_profile_id),
      'following', (select count(*) from follows where follower_id = p_profile_id),
      'reach',     v_reach,
      'media',     (select count(*) from posts p2
                     where p2.user_id = p_profile_id
                       and (p2.media_url is not null
                            or exists (select 1 from post_media m where m.post_id = p2.id))),
      'reposts',   (select count(*) from post_reposts   where user_id = p_profile_id),
      'saved',     (select count(*) from post_bookmarks where user_id = p_profile_id),
      'listings',  (select count(*) from marketplace_listings
                     where seller_id = p_profile_id and status = 'available')
    ),
    'seller_rating', (select jsonb_build_object(
                        'avg', round(coalesce(avg(rating), 0)::numeric, 1),
                        'count', count(*))
                      from seller_reviews where seller_id = p_profile_id),
    'business', case when coalesce(v_row.account_type, 'personal') = 'business' then (
      select jsonb_build_object(
        'category', b.category, 'address', b.address, 'phone', b.phone,
        'email', b.email, 'website', b.website, 'social_links', b.social_links,
        'hours', b.hours,
        'avg_rating', b.avg_rating, 'review_count', b.review_count,
        'is_verified', b.is_verified)
      from business_profiles b where b.profile_id = p_profile_id
    ) else null end,
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', pr.id, 'full_name', pr.full_name,
               'username', pr.username, 'avatar_url', pr.avatar_url, 'role', m.role))
      from business_members m
      join profiles pr on pr.id = m.member_id
      where m.business_id = p_profile_id), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_profile"(p_profile_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_profile"(p_profile_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_profile"(p_profile_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_profile"(p_profile_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."get_profile"(p_profile_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_profile"(p_profile_id uuid) TO "service_role";

CREATE FUNCTION "public"."get_profile_context"(p_profile uuid) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  uid uuid;
  names text[];
  cnt int;
begin
  uid := auth.uid();
  if uid is null then return jsonb_build_object('mutual_names', '{}'::text[], 'mutual_count', 0); end if;
  if uid <> p_profile then
    insert into profile_views (profile_id, viewer_id) values (p_profile, uid)
    on conflict (profile_id, viewer_id, day) do nothing;
  end if;
  select count(*) into cnt
    from follows f1 join follows f2 on f2.follower_id = f1.following_id and f2.following_id = p_profile
    where f1.follower_id = uid and f1.following_id <> uid and f1.following_id <> p_profile;
  select array_agg(nm) into names from (
    select coalesce(p.full_name, '@' || p.username) as nm
      from follows f1
      join follows f2 on f2.follower_id = f1.following_id and f2.following_id = p_profile
      join profiles p on p.id = f1.following_id
      where f1.follower_id = uid and f1.following_id <> uid and f1.following_id <> p_profile
      limit 2) t;
  return jsonb_build_object('mutual_names', coalesce(names, '{}'::text[]), 'mutual_count', coalesce(cnt, 0));
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."get_profile_context"(p_profile uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_profile_context"(p_profile uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_profile_context"(p_profile uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_profile_context"(p_profile uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_profile_context"(p_profile uuid) TO "service_role";

CREATE FUNCTION "public"."get_profile_insights"(p_profile uuid) RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
  select case when auth.uid() = p_profile then jsonb_build_object(
    'views_7d',  (select count(*) from profile_views where profile_id = p_profile and day > current_date - 7),
    'views_30d', (select count(*) from profile_views where profile_id = p_profile and day > current_date - 30),
    'unique_30d',(select count(distinct viewer_id) from profile_views where profile_id = p_profile and day > current_date - 30),
    'new_followers_7d', (select count(*) from follows where following_id = p_profile and created_at > now() - interval '7 days')
  ) else null end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_profile_insights"(p_profile uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_profile_insights"(p_profile uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_profile_insights"(p_profile uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_profile_insights"(p_profile uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_profile_insights"(p_profile uuid) TO "service_role";

CREATE FUNCTION "public"."get_profile_posts"(p_profile_id uuid, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20) RETURNS TABLE(post_id uuid, content text, body text, media_url text, media jsonb, products jsonb, channel text, article_title text, read_minutes integer, created_at timestamp with time zone, likes_count integer, comments_count integer, reposts_count integer, bookmarks_count integer, views_count integer, viewer_liked boolean, viewer_bookmarked boolean, viewer_reposted boolean, is_pinned boolean)
LANGUAGE sql
STABLE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
with viewer as (select auth.uid() as uid),
allowed as (
  select ((select uid from viewer) = p_profile_id)
      or coalesce(pr.profile_visibility, 'public') <> 'private'
      or exists (select 1 from follows f where f.follower_id = (select uid from viewer) and f.following_id = p_profile_id) as ok
  from profiles pr where pr.id = p_profile_id
),
pin as (select pinned_post_id from profiles where id = p_profile_id)
select p.id, p.content, p.body, p.media_url,
  coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'url', m.url, 'media_type', m.media_type, 'width', m.width, 'height', m.height, 'alt_text', m.alt_text, 'is_sensitive', m.is_sensitive, 'sort_order', m.sort_order) order by m.sort_order nulls last) from post_media m where m.post_id = p.id), '[]'::jsonb),
  coalesce((select jsonb_agg(jsonb_build_object('id', pp.id, 'title', pp.title, 'subtitle', pp.subtitle, 'price', pp.price, 'currency', pp.currency, 'image_url', pp.image_url, 'listing_id', pp.listing_id, 'link_url', pp.link_url, 'cta_label', pp.cta_label, 'sort_order', pp.sort_order, 'listing_status', ml.status) order by pp.sort_order) from post_products pp left join marketplace_listings ml on ml.id = pp.listing_id where pp.post_id = p.id), '[]'::jsonb),
  p.channel, p.article_title, p.read_minutes, p.created_at,
  p.likes_count, p.comments_count, p.reposts_count, p.bookmarks_count, p.views_count,
  (lk.user_id is not null), (bk.user_id is not null), (rp.user_id is not null),
  (p.id = (select pinned_post_id from pin))
from posts p
left join post_likes lk     on lk.post_id = p.id and lk.user_id = (select uid from viewer)
left join post_bookmarks bk on bk.post_id = p.id and bk.user_id = (select uid from viewer)
left join post_reposts rp   on rp.post_id = p.id and rp.user_id = (select uid from viewer)
where (p.user_id = p_profile_id
       or exists (select 1 from post_collaborators pc where pc.post_id = p.id and pc.user_id = p_profile_id and pc.status = 'accepted'))
  and p.community_id is null
  and (select ok from allowed)
  and not exists (select 1 from blocked_users b where (b.blocker_id = (select uid from viewer) and b.blocked_id = p.user_id) or (b.blocker_id = p.user_id and b.blocked_id = (select uid from viewer)))
  and (
    coalesce(p.audience, 'everyone') = 'everyone'
    or p.user_id = (select uid from viewer)
    or (p.audience = 'followers' and exists (select 1 from follows f where f.following_id = p.user_id and f.follower_id = (select uid from viewer)))
    or (p.audience = 'mentioned' and exists (select 1 from post_mentions pm where pm.post_id = p.id and pm.mentioned_user_id = (select uid from viewer)))
    or (p.audience = 'verified' and exists (select 1 from profiles vp where vp.id = (select uid from viewer) and vp.is_verified))
  )
  and (p_cursor is null or p.created_at < p_cursor)
order by (case when p_cursor is null and p.id = (select pinned_post_id from pin) then 0 else 1 end), p.created_at desc
limit least(coalesce(p_limit, 20), 50);
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_profile_posts"(p_profile_id uuid, p_cursor timestamp with time zone, p_limit integer) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_profile_posts"(p_profile_id uuid, p_cursor timestamp with time zone, p_limit integer) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_profile_posts"(p_profile_id uuid, p_cursor timestamp with time zone, p_limit integer) TO "postgres";

