CREATE FUNCTION "public"."get_story_poll"(p_story_id uuid) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_poll record;
  v_options jsonb;
  v_my_vote uuid;
  v_total bigint;
BEGIN
  -- Find poll (RLS enforces visibility)
  SELECT id, story_id, question, nx, ny, scale
  INTO v_poll
  FROM story_polls
  WHERE story_id = p_story_id;

  IF v_poll IS NULL THEN
    RETURN NULL;
  END IF;

  -- Get caller's current vote
  SELECT option_id INTO v_my_vote
  FROM story_poll_votes
  WHERE poll_id = v_poll.id AND user_id = auth.uid();

  -- Get total votes
  SELECT count(*) INTO v_total
  FROM story_poll_votes
  WHERE poll_id = v_poll.id;

  -- Get options with vote counts
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'label', o.label,
      'position', o.position,
      'vote_count', (
        SELECT count(*) FROM story_poll_votes v
        WHERE v.option_id = o.id
      )
    ) ORDER BY o.position
  ) INTO v_options
  FROM story_poll_options o
  WHERE o.poll_id = v_poll.id;

  RETURN jsonb_build_object(
    'poll_id', v_poll.id,
    'story_id', v_poll.story_id,
    'question', v_poll.question,
    'nx', v_poll.nx,
    'ny', v_poll.ny,
    'scale', v_poll.scale,
    'options', COALESCE(v_options, '[]'::jsonb),
    'my_vote', v_my_vote,
    'total_votes', v_total
  );
END;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_story_poll"(p_story_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_story_poll"(p_story_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_story_poll"(p_story_id uuid) TO "postgres";

