CREATE FUNCTION "public"."get_sub_communities"(p_community uuid, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, name text, description text, icon_url text, cover_color text, join_mode text, member_count integer, is_member boolean, my_role text, has_pending boolean, has_invite boolean)
