GRANT EXECUTE ON FUNCTION "public"."get_trending_topics"(p_days integer, p_limit integer) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_trending_topics"(p_days integer, p_limit integer) TO "postgres";

