CREATE FUNCTION "public"."get_unread_counts"() RETURNS TABLE(conversation_id uuid, unread integer)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select m.conversation_id, count(*)::int
  from messages m
  where m.receiver_id = auth.uid()
    and m.sender_id <> auth.uid()
    and m.read_at is null
    and m.deleted_at is null
  group by m.conversation_id
  union all
  select m.conversation_id, count(*)::int
  from messages m
  join conversation_members cm
    on cm.conversation_id = m.conversation_id and cm.user_id = auth.uid()
  where m.sender_id <> auth.uid()
    and m.deleted_at is null
    and m.created_at > cm.last_read_at
  group by m.conversation_id;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_unread_counts"() FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"() TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"() TO "anon";

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"() TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"() TO "service_role";

CREATE FUNCTION "public"."get_unread_counts"(p_user_id uuid) RETURNS TABLE(conversation_id uuid, unread_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select conversation_id, sum(unread_count)::bigint as unread_count
  from (
    -- DM branch
    select m.conversation_id, count(*)::bigint as unread_count
    from public.messages m
    join public.conversations c on c.id = m.conversation_id
    where c.is_group = false
      and m.receiver_id = p_user_id
      and m.sender_id <> p_user_id
      and m.viewed_at is null
      and not exists (
        select 1
        from public.message_reads r
        where r.message_id = m.id
          and r.user_id = p_user_id
      )
    group by m.conversation_id

    union all

    -- Group branch
    select m.conversation_id, count(*)::bigint as unread_count
    from public.messages m
    join public.conversations c on c.id = m.conversation_id
    join public.conversation_members cm
      on cm.conversation_id = c.id
     and cm.user_id = p_user_id
    where c.is_group = true
      and m.sender_id <> p_user_id
      and not exists (
        select 1
        from public.message_reads r
        where r.message_id = m.id
          and r.user_id = p_user_id
      )
    group by m.conversation_id
  ) t
  group by conversation_id;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."get_unread_counts"(p_user_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"(p_user_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"(p_user_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."get_unread_counts"(p_user_id uuid) TO "anon";

