CREATE FUNCTION "public"."get_user_highlights"(p_user_id uuid) RETURNS TABLE(id uuid, title text, cover_url text, sort_order integer, story_count bigint, latest_story_media_url text, created_at timestamp with time zone)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
AS $qa_source$
  SELECT
    h.id,
    h.title,
    h.cover_url,
    h.sort_order,
    count(hi.id) as story_count,
    (
      SELECT s.media_url FROM story_highlight_items hi2
      JOIN stories s ON s.id = hi2.story_id
      WHERE hi2.highlight_id = h.id
      ORDER BY hi2.sort_order DESC
      LIMIT 1
    ) as latest_story_media_url,
    h.created_at
  FROM story_highlights h
  LEFT JOIN story_highlight_items hi ON hi.highlight_id = h.id
  WHERE h.user_id = p_user_id
  GROUP BY h.id
  ORDER BY h.sort_order ASC, h.created_at ASC;
$qa_source$;

