CREATE FUNCTION "public"."get_user_stories"(p_user_id uuid) RETURNS TABLE(id uuid, user_id uuid, media_url text, media_type text, thumbnail_url text, duration_sec integer, caption text, scope text, views_count integer, expires_at timestamp with time zone, created_at timestamp with time zone, is_viewed boolean, stickers_json jsonb, text_background jsonb, media_transform jsonb, category text, dual_front_url text, dual_layout jsonb, allow_replies boolean, allow_reactions boolean, allow_sharing boolean, audio_url text, audio_title text, audio_source text, audio_duration_sec integer, filter_id text)
LANGUAGE sql
STABLE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
AS $qa_source$
  select s.id, s.user_id, s.media_url, s.media_type::text, s.thumbnail_url,
    s.duration_sec, s.caption, s.scope::text, s.views_count, s.expires_at, s.created_at,
    exists (select 1 from public.story_views sv where sv.story_id = s.id and sv.user_id = auth.uid()) as is_viewed,
    s.stickers_json, s.text_background, s.media_transform, s.category,
    s.dual_front_url, s.dual_layout,
    s.allow_replies, s.allow_reactions, s.allow_sharing,
    s.audio_url, s.audio_title, s.audio_source, s.audio_duration_sec, s.filter_id
  from public.stories s
  where s.user_id = p_user_id
    and s.expires_at > now()
    and public.viewer_can_see_story(s.id)
  order by s.created_at asc;
$qa_source$;

