CREATE FUNCTION "public"."guard_payment_receipt_message"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public', 'pg_temp'
AS $qa_source$
DECLARE
  v_sensitive boolean := false;
  v_trusted boolean := auth.uid() IS NULL
    AND current_user IN ('postgres', 'service_role', 'supabase_admin');
BEGIN
  IF TG_OP <> 'INSERT' THEN
    v_sensitive := OLD.payment_id IS NOT NULL
      OR OLD.media_type = 'payment'
      OR OLD.payment_receipt_verified;
  END IF;

  IF TG_OP <> 'DELETE' THEN
    v_sensitive := v_sensitive
      OR NEW.payment_id IS NOT NULL
      OR NEW.media_type = 'payment'
      OR NEW.payment_receipt_verified;
  END IF;

  IF coalesce(v_sensitive, false) AND NOT v_trusted THEN
    -- Allow the recipient to acknowledge delivery and reading.
    IF TG_OP = 'UPDATE'
      AND auth.uid() = OLD.receiver_id
      AND (
        to_jsonb(NEW) - ARRAY['read_at', 'viewed_at', 'delivered_at']
      ) = (
        to_jsonb(OLD) - ARRAY['read_at', 'viewed_at', 'delivered_at']
      )
    THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Payment receipt messages are managed by the payment service';
  END IF;

  IF TG_OP <> 'DELETE' AND NEW.payment_receipt_verified THEN
    IF NEW.payment_id IS NULL
      OR NEW.media_type IS DISTINCT FROM 'payment'
      OR NEW.text IS NOT NULL
      OR NOT EXISTS (
        SELECT 1
        FROM public.chat_payments p
        WHERE p.id = NEW.payment_id
          AND p.status = 'completed'
          AND p.tx_id ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND p.conversation_id = NEW.conversation_id
          AND p.sender_id = NEW.sender_id
          AND p.recipient_id = NEW.receiver_id
      )
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'Payment receipt does not match a completed payment';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END
$qa_source$;

REVOKE ALL ON FUNCTION "public"."guard_payment_receipt_message"() FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."guard_payment_receipt_message"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."guard_payment_receipt_message"() TO "service_role";

CREATE FUNCTION "public"."handle_follow_action"(p_target_id uuid) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare
  v_caller uuid := auth.uid();
  v_target_visibility text;
  v_existing_follow uuid;
  v_existing_request uuid;
  v_request_status text;
begin
  if v_caller is null then raise exception 'Not authenticated'; end if;
  if v_caller = p_target_id then raise exception 'Cannot follow yourself'; end if;

  select id into v_existing_follow from follows
  where follower_id = v_caller and following_id = p_target_id;

  if v_existing_follow is not null then
    delete from follows where id = v_existing_follow;
    delete from follow_requests
      where requester_id = v_caller and target_id = p_target_id;
    return jsonb_build_object('action', 'unfollowed');
  end if;

  select id, status into v_existing_request, v_request_status
  from follow_requests where requester_id = v_caller and target_id = p_target_id;

  if v_existing_request is not null then
    if v_request_status = 'pending' then
      delete from follow_requests
        where requester_id = v_caller and target_id = p_target_id;
      return jsonb_build_object('action', 'request_cancelled');
    else
      delete from follow_requests
        where requester_id = v_caller and target_id = p_target_id;
    end if;
  end if;

  select coalesce(profile_visibility, 'public') into v_target_visibility
  from profiles where id = p_target_id;

  if v_target_visibility = 'private' then
    insert into follow_requests (requester_id, target_id, status)
    values (v_caller, p_target_id, 'pending');
    return jsonb_build_object('action', 'requested');
  else
    insert into follows (follower_id, following_id) values (v_caller, p_target_id);
    return jsonb_build_object('action', 'followed');
  end if;
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."handle_follow_action"(p_target_id uuid) TO "service_role";

CREATE FUNCTION "public"."handle_new_user"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  begin
    insert into public.profiles (id, email, full_name, account_type)
    values (
      new.id,
      new.email,
      coalesce(new.raw_user_meta_data->>'full_name', ''),
      'personal'
    )
    on conflict (id) do nothing;
  exception when others then
    raise warning 'handle_new_user profiles insert failed for %: %', new.id, sqlerrm;
  end;

  begin
    insert into public.user_presence (user_id)
    values (new.id)
    on conflict (user_id) do nothing;
  exception when others then
    raise warning 'handle_new_user user_presence insert failed for %: %', new.id, sqlerrm;
  end;

  return new;
end;
$qa_source$;

