CREATE FUNCTION "public"."handle_verified_school_status"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_email TEXT;
  v_domain TEXT;
BEGIN
  SELECT email INTO v_email
  FROM auth.users
  WHERE id = NEW.id;

  IF v_email IS NOT NULL THEN
    v_domain := lower(split_part(v_email, '@', 2));
    NEW.email_domain := v_domain;
    NEW.is_verified_school_user := public.is_verified_school_domain(v_email);
  END IF;

  RETURN NEW;
END;
$qa_source$;

