CREATE FUNCTION "public"."invite_to_community"(p_community uuid, p_user uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_name text; v_actor text;
begin
  if not community_is_mod(p_community) then raise exception 'Only the owner and moderators invite people'; end if;
  if p_user = auth.uid() then raise exception 'You are already here'; end if;
  if exists (select 1 from community_members where community_id = p_community and user_id = p_user) then raise exception 'Already a member'; end if;
  if exists (select 1 from community_bans where community_id = p_community and user_id = p_user) then raise exception 'This person was removed; lift the block first'; end if;
  select name into v_name from communities where id = p_community and status = 'active';
  if v_name is null then raise exception 'No such community'; end if;
  select coalesce(full_name, username, 'Someone') into v_actor from profiles where id = auth.uid();
  insert into community_invites (community_id, user_id, invited_by, status, created_at, responded_at)
  values (p_community, p_user, auth.uid(), 'invited', now(), null)
  on conflict (community_id, user_id) do update set invited_by = excluded.invited_by, status = 'invited', created_at = now(), responded_at = null;
  delete from community_join_requests where community_id = p_community and user_id = p_user;
  delete from notifications where recipient_id = p_user and type = 'community_invite' and data->>'community_id' = p_community::text;
  insert into notifications (recipient_id, actor_id, type, message, data)
  values (p_user, auth.uid(), 'community_invite', v_actor || ' invited you to join ' || v_name,
          jsonb_build_object('community_id', p_community, 'community_name', v_name));
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."invite_to_community"(p_community uuid, p_user uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

