CREATE FUNCTION "public"."is_verified_school_domain"(p_email text) RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_domain TEXT;
BEGIN
  v_domain := lower(split_part(p_email, '@', 2));

  IF v_domain IN ('asu.edu', 'thunderbird.asu.edu') THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$qa_source$;

