CREATE FUNCTION "public"."join_channel"(p_channel uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare uid uuid; ch channels%rowtype;
begin
  uid := auth.uid();
  if uid is null then raise exception 'Not signed in'; end if;
  select * into ch from channels where id = p_channel and status = 'active';
  if not found then raise exception 'Channel not found'; end if;
  if ch.audience = 'followers'
     and ch.owner_id <> uid
     and not exists (select 1 from follows f where f.follower_id = uid and f.following_id = ch.owner_id) then
    raise exception 'This channel is for followers';
  end if;
  insert into channel_members (channel_id, user_id) values (p_channel, uid)
  on conflict (channel_id, user_id) do nothing;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."join_channel"(p_channel uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."join_channel"(p_channel uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."join_channel"(p_channel uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."join_channel"(p_channel uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."join_channel"(p_channel uuid) TO "service_role";

CREATE FUNCTION "public"."join_community"(p_community uuid) RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_mode text;
begin
  select join_mode into v_mode from communities where id = p_community and status = 'active';
  if v_mode is null then raise exception 'No such community'; end if;
  if exists (select 1 from community_members where community_id = p_community and user_id = auth.uid()) then
    return 'joined';
  end if;
  if exists (select 1 from community_bans where community_id = p_community and user_id = auth.uid()) then
    raise exception 'You were removed from this community and cannot rejoin';
  end if;
  if exists (select 1 from community_invites where community_id = p_community and user_id = auth.uid() and status = 'invited') then
    perform community_admit(p_community, auth.uid(), (select invited_by from community_invites where community_id = p_community and user_id = auth.uid()));
    return 'joined';
  end if;
  if v_mode = 'open' then
    perform community_admit(p_community, auth.uid(), null);
    return 'joined';
  elsif v_mode = 'approval' then
    insert into community_join_requests (community_id, user_id) values (p_community, auth.uid())
    on conflict (community_id, user_id) do nothing;
    return 'requested';
  else
    raise exception 'This community is invite only';
  end if;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."join_community"(p_community uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."join_community"(p_community uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."join_community"(p_community uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."join_community"(p_community uuid) TO "service_role";

CREATE FUNCTION "public"."join_community_by_link"(p_token text) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare l record; v_name text;
begin
  select * into l from community_invite_links where token = p_token;
  if not found or l.revoked_at is not null then raise exception 'This invite link is no longer valid'; end if;
  if l.expires_at is not null and l.expires_at <= now() then raise exception 'This invite link has expired'; end if;
  if l.max_uses is not null and l.uses >= l.max_uses then raise exception 'This invite link has been used up'; end if;
  select name into v_name from communities where id = l.community_id and status = 'active';
  if v_name is null then raise exception 'No such community'; end if;
  if exists (select 1 from community_members where community_id = l.community_id and user_id = auth.uid()) then
    return jsonb_build_object('community_id', l.community_id, 'name', v_name, 'status', 'joined');
  end if;
  perform community_admit(l.community_id, auth.uid(), l.created_by);
  update community_invite_links set uses = uses + 1 where id = l.id;
  return jsonb_build_object('community_id', l.community_id, 'name', v_name, 'status', 'joined');
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."join_community_by_link"(p_token text) FROM PUBLIC, anon, authenticated, service_role, postgres;

