CREATE FUNCTION "public"."leave_community"(p_community uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if exists (select 1 from community_members where community_id = p_community and user_id = auth.uid() and role = 'owner') then
    raise exception 'The owner cannot leave their own community';
  end if;
  delete from community_members where community_id = p_community and user_id = auth.uid();
  delete from community_members where user_id = auth.uid() and community_id in (select id from communities where parent_id = p_community) and role <> 'owner';
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."leave_community"(p_community uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

