CREATE FUNCTION "public"."list_my_active_meetings"() RETURNS TABLE(id uuid, room_name text, title text, is_public boolean, expires_at timestamp with time zone, created_at timestamp with time zone, participant_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  select
    m.id, m.room_name, m.title, m.is_public, m.expires_at, m.created_at,
    (select count(*) from public.meeting_participants mp
      where mp.meeting_id = m.id and mp.left_at is null) as participant_count
  from public.meetings m
  where m.host_id = auth.uid()
    and m.ended_at is null
    and m.expires_at > now()
  order by m.created_at desc;
$qa_source$;

