CREATE FUNCTION "public"."mark_conversation_read"(p_conv_id uuid, p_user_id uuid) RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public', 'pg_temp'
AS $qa_source$
DECLARE
  v_updated integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Not authenticated';
  END IF;

  IF p_conv_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Conversation and recipient are required';
  END IF;

  IF NOT public.can_act_as(p_user_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Cannot mark another profile messages as read';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.conversations c
    WHERE c.id = p_conv_id
      AND (
        c.user_1 = p_user_id OR c.user_2 = p_user_id
        OR EXISTS (
          SELECT 1 FROM public.conversation_members cm
          WHERE cm.conversation_id = c.id AND cm.user_id = p_user_id
        )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Conversation is not available';
  END IF;

  UPDATE public.messages
  SET read_at = now(),
      viewed_at = COALESCE(viewed_at, now()),
      delivered_at = COALESCE(delivered_at, now())
  WHERE conversation_id = p_conv_id
    AND receiver_id = p_user_id
    AND sender_id <> p_user_id
    AND read_at IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."mark_conversation_read"(p_conv_id uuid, p_user_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."mark_conversation_read"(p_conv_id uuid, p_user_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."mark_conversation_read"(p_conv_id uuid, p_user_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."mark_conversation_read"(p_conv_id uuid, p_user_id uuid) TO "service_role";

CREATE FUNCTION "public"."mark_conversation_read_v2"(p_conversation_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  update messages set read_at = now()
  where conversation_id = p_conversation_id
    and receiver_id = auth.uid() and read_at is null;

  update conversation_members set last_read_at = now()
  where conversation_id = p_conversation_id and user_id = auth.uid();
end $qa_source$;

