CREATE FUNCTION "public"."notify_story_sticker_response"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_owner uuid; v_name text; v_msg text; v_type text;
begin
  select user_id into v_owner from stories where id = new.story_id;
  if v_owner is null or v_owner = new.user_id then return new; end if;
  if new.response_type = 'notify_done' then return new; end if;
  select coalesce(full_name, username, 'Someone') into v_name from profiles where id = new.user_id;
  v_msg := case new.response_type
    when 'question' then v_name || ' answered your question'
    when 'quiz' then v_name || ' took your quiz'
    when 'slider' then v_name || ' rated your slider'
    when 'countdown' then v_name || ' set a reminder for your countdown'
    when 'addyours' then v_name || ' added theirs to your prompt'
    when 'notify' then v_name || ' asked to be notified'
    when 'magic' then v_name || ' shook your magic ball'
    else v_name || ' responded to your story' end;
  v_type := 'story_' || new.response_type;
  insert into notifications (recipient_id, actor_id, type, message, data)
  values (v_owner, new.user_id, v_type, v_msg, jsonb_build_object('story_id', new.story_id, 'sticker_id', new.sticker_id, 'response_type', new.response_type, 'text', left(coalesce(new.text_value, ''), 120)));
  return new;
end $qa_source$;

