GRANT EXECUTE ON FUNCTION "public"."org_require"(p_org uuid, p_roles text[]) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."org_require"(p_org uuid, p_roles text[]) TO "service_role";

