CREATE FUNCTION "public"."post_community_announcement"(p_community uuid, p_body text) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid;
begin
  if not community_is_mod(p_community) then raise exception 'Only the owner and moderators post announcements'; end if;
  if p_body is null or length(trim(p_body)) < 1 or length(p_body) > 2000 then raise exception 'Announcements run 1 to 2000 characters'; end if;
  insert into community_announcements (community_id, author_id, body) values (p_community, auth.uid(), trim(p_body)) returning id into v_id;
  update communities set last_activity_at = now() where id = p_community;
  return v_id;
end $qa_source$;

