CREATE FUNCTION "public"."post_payment_message"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO ''
AS $qa_source$
BEGIN
  IF NEW.status <> 'completed'
    OR OLD.status IS NOT DISTINCT FROM 'completed'
  THEN
    RETURN NEW;
  END IF;

  IF NEW.tx_id IS NULL OR NEW.tx_id !~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Completed payment requires a canonical transaction reference';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.messages m
    WHERE m.payment_id = NEW.id
      AND m.payment_receipt_verified = true
      AND m.conversation_id = NEW.conversation_id
      AND m.sender_id = NEW.sender_id
      AND m.receiver_id = NEW.recipient_id
      AND m.media_type = 'payment'
      AND m.text IS NULL
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.messages (
    conversation_id,
    sender_id,
    receiver_id,
    text,
    media_type,
    payment_id,
    payment_receipt_verified
  )
  VALUES (
    NEW.conversation_id,
    NEW.sender_id,
    NEW.recipient_id,
    NULL,
    'payment',
    NEW.id,
    true
  );

  UPDATE public.conversations
  SET last_message = 'Payment',
      last_message_time = now(),
      last_message_sender_id = NEW.sender_id
  WHERE id = NEW.conversation_id;

  RETURN NEW;
END
$qa_source$;

REVOKE ALL ON FUNCTION "public"."post_payment_message"() FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."post_payment_message"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."post_payment_message"() TO "service_role";

