CREATE FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text DEFAULT NULL::text, p_cover_width integer DEFAULT NULL::integer, p_cover_height integer DEFAULT NULL::integer) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO ''
AS $qa_source$
declare
  v_post_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_user_id is null or public.can_act_as(p_user_id) is not true then
    raise exception 'You cannot publish as this profile' using errcode = '42501';
  end if;

  insert into public.posts (user_id, body, article_title, read_minutes)
  values (p_user_id, p_body, p_title, p_read_minutes)
  returning id into v_post_id;

  if p_cover_url is not null then
    insert into public.post_media (post_id, url, media_type, sort_order, role, width, height)
    values (v_post_id, p_cover_url, 'image', 0, 'cover', p_cover_width, p_cover_height);
  end if;

  return v_post_id;
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer) TO "service_role";

CREATE FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text DEFAULT NULL::text, p_cover_width integer DEFAULT NULL::integer, p_cover_height integer DEFAULT NULL::integer, p_blocks jsonb DEFAULT NULL::jsonb) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO ''
AS $qa_source$
declare
  v_post_id uuid;
  v_article_id uuid;
  v_revision_id uuid;
  v_cover_asset_id uuid;
  v_block jsonb;
  v_pos integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_user_id is null or public.can_act_as(p_user_id) is not true then
    raise exception 'You cannot publish as this profile' using errcode = '42501';
  end if;

  insert into public.posts (user_id, body, article_title, read_minutes)
  values (p_user_id, p_body, p_title, p_read_minutes)
  returning id into v_post_id;

  if p_cover_url is not null then
    insert into public.post_media (post_id, url, media_type, sort_order, role, width, height)
    values (v_post_id, p_cover_url, 'image', 0, 'cover', p_cover_width, p_cover_height);
  end if;

  if p_blocks is not null then
    if p_cover_url is not null then
      insert into public.media_assets (owner_id, kind, url, width, height)
      values (p_user_id, 'image', p_cover_url, p_cover_width, p_cover_height)
      returning id into v_cover_asset_id;
    end if;

    insert into public.articles (author_id, title, excerpt, cover_asset_id, status, linked_post_id, published_at)
    values (p_user_id, p_title, left(p_body, 200), v_cover_asset_id, 'published', v_post_id, now())
    returning id into v_article_id;

    insert into public.article_revisions (article_id, revision_number, editor_id, published_at)
    values (v_article_id, 1, p_user_id, now())
    returning id into v_revision_id;

    for v_block in select * from jsonb_array_elements(p_blocks)
    loop
      insert into public.article_blocks (revision_id, block_type, position, content)
      values (v_revision_id, v_block->>'type', v_pos, v_block);
      v_pos := v_pos + 1;
    end loop;

    update public.articles set current_revision_id = v_revision_id where id = v_article_id;
  end if;

  return v_post_id;
end;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer, p_blocks jsonb) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer, p_blocks jsonb) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer, p_blocks jsonb) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."publish_article"(p_user_id uuid, p_title text, p_body text, p_read_minutes integer, p_cover_url text, p_cover_width integer, p_cover_height integer, p_blocks jsonb) TO "service_role";

CREATE FUNCTION "public"."push_token_reassign"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  -- A phone's token belongs to the account that is active on it.
  if new.expo_push_token is not null then
    delete from user_push_tokens where expo_push_token = new.expo_push_token and user_id <> new.user_id;
  end if;
  if new.voip_token is not null then
    delete from user_push_tokens where voip_token = new.voip_token and user_id <> new.user_id;
  end if;
  return new;
end $qa_source$;

