CREATE FUNCTION "public"."rank_discover"(p_ids uuid[]) RETURNS TABLE(id uuid, score double precision)
LANGUAGE sql
STABLE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
ROWS 1000
SET search_path TO 'public'
AS $qa_source$
  with base as (
    select p.id, p.user_id, p.created_at,
      coalesce(p.likes_count,0) as likes, coalesce(p.comments_count,0) as comments,
      coalesce(p.reposts_count,0) as reposts, coalesce(p.bookmarks_count,0) as saves, coalesce(p.views_count,0) as views,
      exists (select 1 from public.post_media m where m.post_id = p.id and m.media_type = 'video') as has_video,
      exists (select 1 from public.post_media m where m.post_id = p.id) as has_media,
      exists (select 1 from public.post_seen s where s.post_id = p.id and s.user_id = auth.uid()) as seen
    from public.posts p where p.id = any(p_ids)
  ),
  scored as (
    select id, created_at,
      (likes * 2.0 + comments * 5.0 + reposts * 3.0 + saves * 2.0 + views * 0.05) as engagement,
      extract(epoch from (now() - created_at)) / 3600.0 as age_h,
      has_video, has_media, seen
    from base
  )
  select id,
    (
      (engagement + case when age_h < 6 then 15 else 0 end + case when has_video then 8 when has_media then 4 else 0 end)
      * exp(-age_h / 72.0)
      * case when seen then 0.4 else 1.0 end
      + (engagement + 1) * 0.35 * (('x' || substr(md5(id::text || current_date::text), 1, 8))::bit(32)::bigint::double precision / 4294967295.0)
    )::double precision as score
  from scored;
$qa_source$;

