CREATE FUNCTION "public"."remove_community_member"(p_community uuid, p_user uuid, p_ban boolean DEFAULT false, p_reason text DEFAULT NULL::text) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_role text; v_owner uuid;
begin
  if not community_is_mod(p_community) then raise exception 'Only the owner and moderators remove members'; end if;
  select owner_id into v_owner from communities where id = p_community;
  if p_user = v_owner then raise exception 'The owner cannot be removed'; end if;
  select role into v_role from community_members where community_id = p_community and user_id = p_user;
  if v_role = 'moderator' and v_owner <> auth.uid() then raise exception 'Only the owner removes a moderator'; end if;
  delete from community_members where community_id = p_community and user_id = p_user;
  delete from community_join_requests where community_id = p_community and user_id = p_user;
  update community_invites set status = 'revoked', responded_at = now() where community_id = p_community and user_id = p_user and status = 'invited';
  if p_ban then
    insert into community_bans (community_id, user_id, banned_by, reason) values (p_community, p_user, auth.uid(), nullif(trim(coalesce(p_reason,'')),''))
    on conflict (community_id, user_id) do update set banned_by = excluded.banned_by, reason = excluded.reason, created_at = now();
  end if;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."remove_community_member"(p_community uuid, p_user uuid, p_ban boolean, p_reason text) FROM PUBLIC, anon, authenticated, service_role, postgres;

