CREATE FUNCTION "public"."respond_community_invite"(p_community uuid, p_accept boolean) RETURNS text
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_by uuid;
begin
  select invited_by into v_by from community_invites where community_id = p_community and user_id = auth.uid() and status = 'invited';
  if not found then raise exception 'No invitation found'; end if;
  if p_accept then
    perform community_admit(p_community, auth.uid(), v_by);
    return 'joined';
  end if;
  update community_invites set status = 'declined', responded_at = now() where community_id = p_community and user_id = auth.uid();
  delete from notifications where recipient_id = auth.uid() and type = 'community_invite' and data->>'community_id' = p_community::text;
  return 'declined';
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."respond_community_invite"(p_community uuid, p_accept boolean) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."respond_community_invite"(p_community uuid, p_accept boolean) TO PUBLIC;

