CREATE FUNCTION "public"."set_comment_spam"(p_comment_id uuid, p_spam boolean) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_author uuid;
begin
  select p.user_id into v_author from post_comments c join posts p on p.id = c.post_id where c.id = p_comment_id;
  if v_author is null or v_author <> auth.uid() then raise exception 'Only the post author reviews spam'; end if;
  update post_comments set is_spam = p_spam, spam_reason = case when p_spam then coalesce(spam_reason, 'marked by author') else spam_reason end, spam_reviewed_at = now() where id = p_comment_id;
end $qa_source$;

