CREATE FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_role text;
begin
  if not community_is_mod(p_community) then raise exception 'Only the owner and moderators change what members can do'; end if;
  if p_status not in ('active','limited') then raise exception 'Bad status'; end if;
  select role into v_role from community_members where community_id = p_community and user_id = p_user;
  if v_role is null then raise exception 'Not a member'; end if;
  if v_role = 'owner' then raise exception 'The owner cannot be limited'; end if;
  if v_role = 'moderator' and not exists (select 1 from communities where id = p_community and owner_id = auth.uid()) then raise exception 'Only the owner limits a moderator'; end if;
  update community_members set status = p_status, status_at = now() where community_id = p_community and user_id = p_user;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."set_community_member_status"(p_community uuid, p_user uuid, p_status text) TO "service_role";

CREATE FUNCTION "public"."set_community_role"(p_community uuid, p_user uuid, p_role text) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_owner uuid;
begin
  select owner_id into v_owner from communities where id = p_community;
  if v_owner is null then raise exception 'No such community'; end if;
  if v_owner <> auth.uid() then raise exception 'Only the owner manages roles'; end if;
  if p_user = v_owner then raise exception 'The owner role cannot change'; end if;
  if p_role = 'remove' then
    delete from community_members where community_id = p_community and user_id = p_user;
    return;
  end if;
  if p_role not in ('moderator','member') then raise exception 'Bad role'; end if;
  insert into community_members (community_id, user_id, role) values (p_community, p_user, p_role)
  on conflict (community_id, user_id) do update set role = excluded.role;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."set_community_role"(p_community uuid, p_user uuid, p_role text) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."set_community_role"(p_community uuid, p_user uuid, p_role text) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."set_community_role"(p_community uuid, p_user uuid, p_role text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."set_community_role"(p_community uuid, p_user uuid, p_role text) TO "service_role";

CREATE FUNCTION "public"."set_disappearing_messages"(p_conversation_id uuid, p_seconds integer DEFAULT NULL::integer) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if auth.uid() is null then raise exception 'Not authenticated'; end if;
  if not exists (
    select 1 from conversations c
    where c.id = p_conversation_id
      and (c.user_1 = auth.uid() or c.user_2 = auth.uid()
           or exists (select 1 from conversation_members m
                      where m.conversation_id = c.id and m.user_id = auth.uid()))
  ) then
    raise exception 'Not a participant in this conversation';
  end if;

  update conversations
     set disappearing_seconds = p_seconds,
         disappearing_set_by = auth.uid(),
         disappearing_set_at = now()
   where id = p_conversation_id;
end;
$qa_source$;

