GRANT EXECUTE ON FUNCTION "public"."set_post_products"(p_post_id uuid, p_products jsonb) TO "service_role";

CREATE FUNCTION "public"."set_restriction"(p_user uuid, p_on boolean) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if p_user = auth.uid() then raise exception 'You cannot restrict yourself'; end if;
  if p_on then
    insert into user_restrictions (restrictor_id, restricted_id) values (auth.uid(), p_user) on conflict do nothing;
  else
    delete from user_restrictions where restrictor_id = auth.uid() and restricted_id = p_user;
  end if;
end $qa_source$;

