CREATE FUNCTION "public"."studio_delete_campaign"(p_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare c record;
begin
  perform studio_require(array['owner','admin']);
  select * into c from studio_campaigns where id = p_id and owner_id = auth.uid();
  if c is null then raise exception 'No such campaign'; end if;
  if c.status not in ('draft','rejected') then raise exception 'Only drafts and rejected campaigns can be deleted. End a running campaign instead.'; end if;
  delete from promoted_posts where campaign_id = p_id;
  delete from studio_campaigns where id = p_id;
end $qa_source$;

