CREATE FUNCTION "public"."studio_save_campaign"(p_id uuid, p_name text, p_objective text, p_budget numeric, p_currency text, p_payment_method text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid;
begin
  perform studio_require(array['owner','admin']);
  if coalesce(trim(p_name),'') = '' then raise exception 'Give the campaign a name'; end if;
  if p_ends_at is not null and p_starts_at is not null and p_ends_at <= p_starts_at then raise exception 'End must be after start'; end if;
  if p_id is null then
    insert into studio_campaigns (owner_id, name, objective, budget, currency, payment_method, starts_at, ends_at)
    values (auth.uid(), trim(p_name), coalesce(p_objective,'reach'), coalesce(p_budget,0), coalesce(p_currency,'USD'), p_payment_method, p_starts_at, p_ends_at)
    returning id into v_id;
  else
    update studio_campaigns set name = trim(p_name), objective = coalesce(p_objective, objective), budget = coalesce(p_budget, budget), currency = coalesce(p_currency, currency),
      payment_method = coalesce(p_payment_method, payment_method), starts_at = p_starts_at, ends_at = p_ends_at, updated_at = now(),
      status = case when status in ('rejected') then 'draft' else status end
    where id = p_id and owner_id = auth.uid() and status in ('draft','rejected','paused','approved') returning id into v_id;
    if v_id is null then raise exception 'Campaign cannot be edited in its current state'; end if;
    update promoted_posts set starts_at = coalesce(p_starts_at, now()), ends_at = p_ends_at where campaign_id = v_id;
  end if;
  return v_id;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."studio_save_campaign"(p_id uuid, p_name text, p_objective text, p_budget numeric, p_currency text, p_payment_method text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."studio_save_campaign"(p_id uuid, p_name text, p_objective text, p_budget numeric, p_currency text, p_payment_method text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."studio_save_campaign"(p_id uuid, p_name text, p_objective text, p_budget numeric, p_currency text, p_payment_method text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."studio_save_campaign"(p_id uuid, p_name text, p_objective text, p_budget numeric, p_currency text, p_payment_method text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone) TO "service_role";

