CREATE FUNCTION "public"."studio_save_post"(p_id uuid DEFAULT NULL::uuid, p_content text DEFAULT NULL::text, p_body text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_community uuid DEFAULT NULL::uuid, p_media jsonb DEFAULT '[]'::jsonb, p_products jsonb DEFAULT '[]'::jsonb, p_publish_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_id uuid; v_status text;
begin
  if coalesce(trim(p_content),'') = '' and coalesce(trim(p_body),'') = '' and jsonb_array_length(coalesce(p_media,'[]'::jsonb)) = 0 then
    raise exception 'A post needs text or media';
  end if;
  v_status := case when p_publish_at is null then 'draft' else 'scheduled' end;
  if p_publish_at is not null and p_publish_at < now() - interval '1 minute' then raise exception 'Publish time is in the past'; end if;
  if p_id is null then
    insert into studio_scheduled_posts (owner_id, status, publish_at, content, body, category, community_id, media, products)
    values (auth.uid(), v_status, p_publish_at, p_content, p_body, p_category, p_community, coalesce(p_media,'[]'::jsonb), coalesce(p_products,'[]'::jsonb))
    returning id into v_id;
  else
    update studio_scheduled_posts set status = v_status, publish_at = p_publish_at, content = p_content, body = p_body,
      category = p_category, community_id = p_community, media = coalesce(p_media,'[]'::jsonb), products = coalesce(p_products,'[]'::jsonb),
      error = null, updated_at = now()
    where id = p_id and owner_id = auth.uid() and status in ('draft','scheduled','failed','cancelled')
    returning id into v_id;
    if v_id is null then raise exception 'Not found or already published'; end if;
  end if;
  return v_id;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."studio_save_post"(p_id uuid, p_content text, p_body text, p_category text, p_community uuid, p_media jsonb, p_products jsonb, p_publish_at timestamp with time zone) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."studio_save_post"(p_id uuid, p_content text, p_body text, p_category text, p_community uuid, p_media jsonb, p_products jsonb, p_publish_at timestamp with time zone) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."studio_save_post"(p_id uuid, p_content text, p_body text, p_category text, p_community uuid, p_media jsonb, p_products jsonb, p_publish_at timestamp with time zone) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."studio_save_post"(p_id uuid, p_content text, p_body text, p_category text, p_community uuid, p_media jsonb, p_products jsonb, p_publish_at timestamp with time zone) TO "service_role";

CREATE FUNCTION "public"."studio_schedule_interview"(p_application uuid, p_at timestamp with time zone, p_location text) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare a record;
begin
  perform studio_require(array['owner','admin','recruiter']);
  select a1.*, j.title as job_title into a from job_applications a1 join jobs j on j.id = a1.job_id where a1.id = p_application and j.posted_by = auth.uid();
  if a is null then raise exception 'Not your application'; end if;
  update job_applications set interview_at = p_at, interview_location = nullif(trim(coalesce(p_location,'')),''),
    status = case when p_at is null then status else 'interview' end, updated_at = now() where id = p_application;
  if p_at is not null then
    insert into notifications (recipient_id, actor_id, type, message, data)
    values (a.applicant_id, auth.uid(), 'job_interview',
      'Interview for ' || a.job_title || ' on ' || to_char(p_at at time zone 'Africa/Harare', 'Dy DD Mon HH24:MI') || coalesce(' at ' || nullif(trim(coalesce(p_location,'')),''), ''),
      jsonb_build_object('job_id', a.job_id, 'application_id', a.id, 'interview_at', p_at, 'location', p_location));
  end if;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."studio_schedule_interview"(p_application uuid, p_at timestamp with time zone, p_location text) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."studio_schedule_interview"(p_application uuid, p_at timestamp with time zone, p_location text) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."studio_schedule_interview"(p_application uuid, p_at timestamp with time zone, p_location text) TO "authenticated";

