CREATE FUNCTION "public"."submit_sticker_response"(p_story_id uuid, p_sticker_id text, p_response_type text, p_text_value text DEFAULT NULL::text, p_number_value numeric DEFAULT NULL::numeric, p_option_id text DEFAULT NULL::text) RETURNS json
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE v_result story_sticker_responses;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.viewer_can_see_story(p_story_id) THEN RAISE EXCEPTION 'Cannot access this story'; END IF;
  IF p_response_type NOT IN ('question', 'slider', 'quiz', 'countdown', 'addyours', 'notify', 'magic') THEN RAISE EXCEPTION 'Invalid response type'; END IF;
  IF p_response_type = 'slider' AND (p_number_value IS NULL OR p_number_value < 0 OR p_number_value > 1) THEN RAISE EXCEPTION 'Slider value must be between 0 and 1'; END IF;
  IF p_response_type = 'question' AND (p_text_value IS NULL OR length(trim(p_text_value)) < 1) THEN RAISE EXCEPTION 'Answer cannot be empty'; END IF;
  IF p_response_type = 'question' THEN
    INSERT INTO story_sticker_responses (story_id, sticker_id, user_id, response_type, text_value)
    VALUES (p_story_id, p_sticker_id, auth.uid(), 'question', p_text_value) RETURNING * INTO v_result;
  ELSE
    INSERT INTO story_sticker_responses (story_id, sticker_id, user_id, response_type, text_value, number_value, option_id)
    VALUES (p_story_id, p_sticker_id, auth.uid(), p_response_type, p_text_value, p_number_value, p_option_id)
    ON CONFLICT (story_id, sticker_id, user_id) WHERE response_type <> 'question'
    DO UPDATE SET response_type = EXCLUDED.response_type,
      text_value = COALESCE(p_text_value, story_sticker_responses.text_value),
      number_value = COALESCE(p_number_value, story_sticker_responses.number_value),
      option_id = COALESCE(p_option_id, story_sticker_responses.option_id), created_at = now()
    RETURNING * INTO v_result;
  END IF;
  RETURN row_to_json(v_result);
END; $qa_source$;

REVOKE ALL ON FUNCTION "public"."submit_sticker_response"(p_story_id uuid, p_sticker_id text, p_response_type text, p_text_value text, p_number_value numeric, p_option_id text) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."submit_sticker_response"(p_story_id uuid, p_sticker_id text, p_response_type text, p_text_value text, p_number_value numeric, p_option_id text) TO PUBLIC;

