CREATE FUNCTION "public"."sync_application_count"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
begin
  if TG_OP = 'INSERT' then
    update jobs set application_count = coalesce(application_count, 0) + 1
    where id = NEW.job_id;
  elsif TG_OP = 'DELETE' then
    update jobs set application_count = greatest(0, coalesce(application_count, 0) - 1)
    where id = OLD.job_id;
  end if;
  return coalesce(NEW, OLD);
end;
$qa_source$;

