CREATE FUNCTION "public"."sync_post_counter_exact"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_post uuid;
begin
  v_post := coalesce(new.post_id, old.post_id);
  if v_post is null then return null; end if;
  if tg_table_name = 'post_reposts' then
    update posts set reposts_count = (select count(*) from post_reposts r where r.post_id = v_post) where id = v_post;
  elsif tg_table_name = 'post_bookmarks' then
    update posts set bookmarks_count = (select count(*) from post_bookmarks b where b.post_id = v_post) where id = v_post;
  elsif tg_table_name = 'post_comments' then
    update posts set comments_count = (select count(*) from post_comments c where c.post_id = v_post) where id = v_post;
  elsif tg_table_name = 'post_seen' then
    update posts p set views_count = (select count(*) from post_seen s where s.post_id = v_post and s.user_id <> p.user_id) where p.id = v_post;
  end if;
  return null;
end $qa_source$;

