CREATE FUNCTION "public"."tg_comment_spam"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_author uuid; v_body text; v_reason text; v_created timestamptz;
begin
  if new.is_spam then return new; end if;
  select user_id into v_author from posts where id = new.post_id;
  if v_author is null or v_author = new.user_id then return new; end if;
  if exists (select 1 from follows where follower_id = v_author and following_id = new.user_id) then return new; end if;
  v_body := lower(coalesce(new.body, new.content, ''));
  select created_at into v_created from profiles where id = new.user_id;
  if v_body ~ '(https?://|www\.|wa\.me|t\.me|bit\.ly)' then v_reason := 'link';
  elsif v_body ~ '(forex|binary option|crypto|bitcoin|double your money|investment plan|dm me|whatsapp \+|cash ?app|earn \$|make money fast)' then v_reason := 'scam words';
  elsif (select count(*) from post_comments c where c.user_id = new.user_id and c.created_at > now() - interval '24 hours' and lower(coalesce(c.body, c.content, '')) = v_body) >= 2 then v_reason := 'repeated';
  elsif (select count(*) from post_comments c where c.user_id = new.user_id and c.created_at > now() - interval '60 seconds') >= 8 then v_reason := 'burst';
  elsif v_created > now() - interval '2 days' and v_body ~ '\+?\d[\d ]{8,}' then v_reason := 'new account with a number';
  end if;
  if v_reason is not null then new.is_spam := true; new.spam_reason := v_reason; end if;
  return new;
end $qa_source$;

