CREATE FUNCTION "public"."tg_message_restrict"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v record; v_other uuid;
begin
  select is_group, user_1, user_2, request_status into v from conversations where id = new.conversation_id;
  if v.is_group or v.user_1 is null or v.user_2 is null then return new; end if;
  v_other := case when v.user_1 = new.sender_id then v.user_2 else v.user_1 end;
  if v.request_status <> 'accepted' and exists (select 1 from user_restrictions where restrictor_id = v_other and restricted_id = new.sender_id) then
    update conversations set request_status = 'pending', is_request = true, request_sender_id = new.sender_id, requested_at = coalesce(requested_at, now())
    where id = new.conversation_id and request_status <> 'pending';
  end if;
  return new;
end $qa_source$;

