CREATE FUNCTION "public"."tg_posts_community_guard"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_status text;
begin
  if new.community_id is not null and auth.uid() is not null then
    select status into v_status from community_members m where m.community_id = new.community_id and m.user_id = auth.uid();
    if v_status is null then raise exception 'Join the community before posting in it'; end if;
    if v_status = 'limited' then raise exception 'You can view this community but not post in it'; end if;
  end if;
  return new;
end $qa_source$;

