CREATE FUNCTION "public"."toggle_post_like"(p_post_id uuid) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
DECLARE
  v_user_id uuid;
  v_existing boolean;
  v_count integer;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Lock target post so count reconciliation is stable.
  PERFORM 1
  FROM public.posts
  WHERE id = p_post_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Post not found';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.post_likes
    WHERE post_id = p_post_id
      AND user_id = v_user_id
  ) INTO v_existing;

  IF v_existing THEN
    DELETE FROM public.post_likes
    WHERE post_id = p_post_id
      AND user_id = v_user_id;

    -- Trigger updates posts.likes_count. Re-read final value.
    SELECT COALESCE(likes_count, 0)
    INTO v_count
    FROM public.posts
    WHERE id = p_post_id;

    RETURN jsonb_build_object(
      'post_id', p_post_id,
      'liked', false,
      'likes_count', v_count
    );
  ELSE
    INSERT INTO public.post_likes(post_id, user_id)
    VALUES (p_post_id, v_user_id)
    ON CONFLICT (post_id, user_id) DO NOTHING;

    -- Trigger updates posts.likes_count. Re-read final value.
    SELECT COALESCE(likes_count, 0)
    INTO v_count
    FROM public.posts
    WHERE id = p_post_id;

    RETURN jsonb_build_object(
      'post_id', p_post_id,
      'liked', true,
      'likes_count', v_count
    );
  END IF;
END;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."toggle_post_like"(p_post_id uuid) TO "service_role";

CREATE FUNCTION "public"."toggle_story_reaction"(p_story_id uuid, p_emoji text) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  -- Try to delete existing reaction
  DELETE FROM story_reactions
  WHERE story_id = p_story_id
    AND user_id = v_uid
    AND emoji = p_emoji;

  IF FOUND THEN
    -- Reaction existed and was removed
    RETURN jsonb_build_object('reacted', false, 'emoji', p_emoji);
  END IF;

  -- No existing reaction, insert new one
  INSERT INTO story_reactions (story_id, user_id, emoji)
  VALUES (p_story_id, v_uid, p_emoji);

  RETURN jsonb_build_object('reacted', true, 'emoji', p_emoji);
END;
$qa_source$;

