LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if new.mentioned_user_id = new.mentioned_by_user_id then return new; end if;
  insert into public.notifications (recipient_id, actor_id, type, message, body_preview, data, account_type)
  select new.mentioned_user_id, new.mentioned_by_user_id, 'story_mention', 'mentioned you in their story',
         nullif(left(coalesce(s.caption, ''), 100), ''),
         jsonb_build_object('story_id', new.story_id, 'visible', new.visible, 'allow_reshare', new.allow_reshare),
         'personal'
  from public.stories s where s.id = new.story_id;
  return new;
end $qa_source$;

