CREATE FUNCTION "public"."update_business_advert_count"() RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
DECLARE
  v_business_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_business_id := OLD.business_id;
  ELSE
    v_business_id := NEW.business_id;
  END IF;

  UPDATE business_profiles
  SET advert_count = (
        SELECT COUNT(*)
        FROM business_posts
        WHERE business_id = v_business_id
      ),
      updated_at = now()
  WHERE id = v_business_id;

  RETURN COALESCE(NEW, OLD);
END;
$qa_source$;

