CREATE FUNCTION "public"."update_channel_settings"(p_channel uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_audience text DEFAULT NULL::text, p_replies_enabled boolean DEFAULT NULL::boolean, p_icon_url text DEFAULT NULL::text) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if not exists (select 1 from channels c where c.id = p_channel and c.owner_id = auth.uid()) then
    raise exception 'Only the owner can edit channel settings';
  end if;
  if p_audience is not null and p_audience not in ('everyone','followers') then
    raise exception 'Bad audience';
  end if;
  update channels set
    name = coalesce(nullif(trim(p_name), ''), name),
    description = coalesce(p_description, description),
    audience = coalesce(p_audience, audience),
    replies_enabled = coalesce(p_replies_enabled, replies_enabled),
    icon_url = coalesce(p_icon_url, icon_url)
  where id = p_channel;
end $qa_source$;

