GRANT EXECUTE ON FUNCTION "public"."viewer_can_see_story"(p_story_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."viewer_can_see_story"(p_story_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."viewer_can_see_story"(p_story_id uuid) TO "service_role";

CREATE FUNCTION "public"."vote_channel_poll"(p_message uuid, p_option uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
declare v_channel uuid; v_ends timestamptz;
begin
  select m.channel_id, pl.ends_at into v_channel, v_ends
  from channel_messages m join channel_polls pl on pl.message_id = m.id
  where m.id = p_message;
  if v_channel is null then raise exception 'No poll on that message'; end if;
  if v_ends < now() then raise exception 'This poll has closed'; end if;
  if not exists (select 1 from channel_members where channel_id = v_channel and user_id = auth.uid()) then
    raise exception 'Join the channel to vote';
  end if;
  if not exists (select 1 from channel_poll_options o where o.id = p_option and o.message_id = p_message) then
    raise exception 'Bad option';
  end if;
  insert into channel_poll_votes (message_id, user_id, option_id)
  values (p_message, auth.uid(), p_option)
  on conflict (message_id, user_id) do update set option_id = excluded.option_id, created_at = now();
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."vote_channel_poll"(p_message uuid, p_option uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."vote_channel_poll"(p_message uuid, p_option uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."vote_channel_poll"(p_message uuid, p_option uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."vote_channel_poll"(p_message uuid, p_option uuid) TO "service_role";

CREATE FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if exists (select 1 from posts where id = p_post_id and user_id = auth.uid()) then raise exception 'You cannot vote on your own poll'; end if;
  if not exists (select 1 from post_polls where post_id = p_post_id and now() < ends_at) then raise exception 'This poll has ended'; end if;
  if not exists (select 1 from post_poll_options where id = p_option_id and post_id = p_post_id) then raise exception 'Option not in this poll'; end if;
  insert into post_poll_votes (post_id, option_id, voter_id) values (p_post_id, p_option_id, auth.uid())
  on conflict (post_id, voter_id) do update set option_id = excluded.option_id;
end $qa_source$;

REVOKE ALL ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) TO PUBLIC;

GRANT EXECUTE ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) TO "anon";

GRANT EXECUTE ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."vote_poll"(p_post_id uuid, p_option_id uuid) TO "service_role";

CREATE FUNCTION "public"."vote_story_poll"(p_poll_id uuid, p_option_id uuid) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
AS $qa_source$
DECLARE
  v_option_poll_id uuid;
  v_story_id uuid;
BEGIN
  -- Verify option belongs to this poll
  SELECT poll_id INTO v_option_poll_id
  FROM story_poll_options
  WHERE id = p_option_id;

  IF v_option_poll_id IS NULL THEN
    RAISE EXCEPTION 'Option not found';
  END IF;

  IF v_option_poll_id != p_poll_id THEN
    RAISE EXCEPTION 'Option does not belong to this poll';
  END IF;

  -- Upsert vote
  INSERT INTO story_poll_votes (poll_id, option_id, user_id)
  VALUES (p_poll_id, p_option_id, auth.uid())
  ON CONFLICT (poll_id, user_id)
  DO UPDATE SET option_id = EXCLUDED.option_id, updated_at = now();

  -- Get story_id to return updated results
  SELECT story_id INTO v_story_id
  FROM story_polls WHERE id = p_poll_id;

  -- Return fresh results
  RETURN get_story_poll(v_story_id);
END;
$qa_source$;

REVOKE ALL ON FUNCTION "public"."vote_story_poll"(p_poll_id uuid, p_option_id uuid) FROM PUBLIC, anon, authenticated, service_role, postgres;

GRANT EXECUTE ON FUNCTION "public"."vote_story_poll"(p_poll_id uuid, p_option_id uuid) TO PUBLIC;

