CREATE FUNCTION "public"."vouch_for"(p_user_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
