GRANT EXECUTE ON FUNCTION "public"."vouch_for"(p_user_id uuid, p_note text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."vouch_for"(p_user_id uuid, p_note text) TO "service_role";

CREATE FUNCTION "public"."withdraw_mentorship_request"(p_request_id uuid) RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
CALLED ON NULL INPUT
PARALLEL UNSAFE
COST 100
SET search_path TO 'public'
AS $qa_source$
begin
  update public.mentorship_requests
     set status = 'withdrawn', responded_at = now()
   where id = p_request_id and mentee_id = auth.uid() and status = 'pending';

  if not found then raise exception 'Request not found or not yours'; end if;
end;
$qa_source$;

