CREATE POLICY "ad_events_insert_own" ON "public"."ad_events" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "ad_events_select_advertiser" ON "public"."ad_events" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM promoted_posts pp
  WHERE ((pp.id = ad_events.promo_id) AND can_act_as(pp.advertiser_id)))));

CREATE POLICY "audit_select" ON "public"."admin_audit_log" AS PERMISSIVE FOR SELECT TO "authenticated" USING (is_admin());

CREATE POLICY "admin_users_select" ON "public"."admin_users" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((user_id = auth.uid()));

CREATE POLICY "announcements_read_active" ON "public"."announcements" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((active = true));

CREATE POLICY "events_insert_own" ON "public"."app_events" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "blocks_published_read" ON "public"."article_blocks" AS PERMISSIVE FOR SELECT TO "public" USING ((EXISTS ( SELECT 1
   FROM (article_revisions r
     JOIN articles a ON ((a.id = r.article_id)))
  WHERE ((r.id = article_blocks.revision_id) AND (a.current_revision_id = r.id) AND (a.status = 'published'::text) AND (a.audience = 'everyone'::text)))));

CREATE POLICY "blocks_via_revision" ON "public"."article_blocks" AS PERMISSIVE FOR ALL TO "public" USING ((EXISTS ( SELECT 1
   FROM (article_revisions r
     JOIN articles a ON ((a.id = r.article_id)))
  WHERE ((r.id = article_blocks.revision_id) AND (a.author_id = auth.uid())))));

CREATE POLICY "revisions_published_read" ON "public"."article_revisions" AS PERMISSIVE FOR SELECT TO "public" USING ((EXISTS ( SELECT 1
   FROM articles a
  WHERE ((a.id = article_revisions.article_id) AND (a.current_revision_id = article_revisions.id) AND (a.status = 'published'::text) AND (a.audience = 'everyone'::text)))));

CREATE POLICY "revisions_via_article" ON "public"."article_revisions" AS PERMISSIVE FOR ALL TO "public" USING ((EXISTS ( SELECT 1
   FROM articles a
  WHERE ((a.id = article_revisions.article_id) AND (a.author_id = auth.uid())))));

CREATE POLICY "articles_author_all" ON "public"."articles" AS PERMISSIVE FOR ALL TO "public" USING ((author_id = auth.uid())) WITH CHECK ((author_id = auth.uid()));

CREATE POLICY "articles_public_read" ON "public"."articles" AS PERMISSIVE FOR SELECT TO "public" USING (((status = 'published'::text) AND (audience = 'everyone'::text)));

