  SELECT count(*) INTO mismatches FROM expected e LEFT JOIN (pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace AND n.nspname='public') ON p.proname=e.name AND pg_get_function_identity_arguments(p.oid)=e.args
  WHERE p.oid IS NULL OR md5(pg_get_functiondef(p.oid))<>e.definition_hash OR md5(p.prosrc)<>e.body_hash;
  IF mismatches<>0 THEN RAISE EXCEPTION 'QA routine hash mismatch: %',mismatches; END IF;
  IF md5(pg_get_functiondef('platinum_internal.guard_job_application_write()'::regprocedure))<>'2c6fed9212d1e0af8ecd3fa32d818ca8' THEN RAISE EXCEPTION 'QA private job guard hash mismatch'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p'))<>156 THEN RAISE EXCEPTION 'QA table count mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity) THEN RAISE EXCEPTION 'QA RLS missing'; END IF;
  IF (SELECT count(*) FROM pg_policies WHERE schemaname IN ('public','storage'))<>408 THEN RAISE EXCEPTION 'QA policy count mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('notify_push_notification','notify_voip_ring','notify_voip_ring_1to1','notify_voip_ring_session')) THEN RAISE EXCEPTION 'QA external hook was restored'; END IF;
  IF EXISTS (SELECT 1 FROM auth.users) OR EXISTS (SELECT 1 FROM storage.objects) OR EXISTS (SELECT 1 FROM storage.buckets) OR EXISTS (SELECT 1 FROM vault.secrets) OR EXISTS (SELECT 1 FROM net.http_request_queue) THEN RAISE EXCEPTION 'QA data or outbound side effect detected'; END IF;
